6: 
7: @Injectable({
8:   providedIn: 'root',
9: })
10: export class UserService {
11:   private user$ = new BehaviorSubject(null);
12: 
13:   constructor(private requestManager: RequestManager) {
14:     this.getUserInfo();
15:   }
16: 
17:   private getUserInfo() {
18:     const userLocalStorageEncode = window.localStorage.getItem('user');
19:     const userLocalStorage = userLocalStorageEncode
20:       ? JSON.parse(atob(userLocalStorageEncode))
21:       : null;
22:     this.user$.next(userLocalStorage);
23:   }
24: 
25:   public getUser() {
26:     return this.user$.asObservable();
27:   }
28: 
29:   public getPayload(): any {
30:     var payload: any = {};
31:     const idToken = window.localStorage.getItem('id_token')?.split('.');
32:     if (idToken != undefined) {
33:       payload = JSON.parse(atob(idToken[1]));
34:     }
35:     return payload;
36:   }
37: 
38:   public esAutorizado(requiredRoles: string[]): Promise<boolean> {
39:     return new Promise((resolve, reject) => {
40:       this.getUser().subscribe(
41:         (user: any) => {
42:           if (user && user.user && user['user'].role) {
43:             const roles = [
44:               ...new Set([...user['user'].role]),
45:               ...user['userService'].role,
46:             ];
47:             const isAuthorized = requiredRoles.some((role) =>
48:               roles.includes(role)
49:             );
50:             resolve(isAuthorized);
51:           } else {
52:             resolve(false);
53:           }
54:         },
55:         (error) => {
56:           reject(error);
57:         }
58:       );
59:     });
60:   }
61: 
62:   public getEmail(): Promise<string> {
63:     return new Promise((resolve, reject) => {
64:       this.getUser().subscribe(
65:         ({ user }: any) => {
66:           if (user && user.email) {
67:             resolve(user['email']);
68:           } else {
69:             resolve('');
70:           }
71:         },
72:         (error) => {
73:           console.error('Error al obtener el usuario', error);
74:           reject(error);
75:         }
76:       );
77:     });
78:   }
